    return 'RBF{rbfId: ${rbfId}, bodyName: ${bodyName}, bodyNaifId: ${bodyNaifId}, MODEL: ${MODEL}, modelVersion: ${modelVersion}, magModelId: ${magModelId}, referenceFrame: ${referenceFrame}, SPECIES: ${SPECIES}, fluxType: ${fluxType}, UNITS: ${UNITS}, EPOCH: ${EPOCH}, KP: ${KP}, hasKp: ${hasKp}, dstNt: ${dstNt}, hasDstNt: ${hasDstNt}, F107: ${F107}, hasF107: ${hasF107}, solarWindPressureNpa: ${solarWindPressureNpa}, hasSolarWindPressure: ${hasSolarWindPressure}, quantilePct: ${quantilePct}, lShells: ${lShells}, energyMev: ${energyMev}, bOverB0: ${bOverB0}, fluxGrid: ${fluxGrid}, STRUCTURES: ${STRUCTURES}, saaContours: ${saaContours}, spaceWeatherRefs: ${spaceWeatherRefs}, PROVENANCE: ${PROVENANCE}}';
  }
}

class _RBFReader extends fb.TableReader<RBF> {
  const _RBFReader();

  @override
  RBF createObject(fb.BufferContext bc, int offset) =>
    RBF._(bc, offset);
}

class RBFBuilder {
  RBFBuilder(this.fbBuilder);

  final fb.Builder fbBuilder;

  void begin() {
    fbBuilder.startTable(28);
  }

  int addRbfIdOffset(int? offset) {
    fbBuilder.addOffset(0, offset);
    return fbBuilder.offset;
  }
  int addBodyNameOffset(int? offset) {
    fbBuilder.addOffset(1, offset);
    return fbBuilder.offset;
  }
  int addBodyNaifId(int? BODY_NAIF_ID) {
    fbBuilder.addInt32(2, BODY_NAIF_ID);
    return fbBuilder.offset;
  }
  int addModel(rbfModelKind? MODEL) {
    fbBuilder.addInt8(3, MODEL?.value);
    return fbBuilder.offset;
