    fbBuilder.addOffset(4, offset);
    return fbBuilder.offset;
  }
  int addMagModelIdOffset(int? offset) {
    fbBuilder.addOffset(5, offset);
    return fbBuilder.offset;
  }
  int addReferenceFrameOffset(int? offset) {
    fbBuilder.addOffset(6, offset);
    return fbBuilder.offset;
  }
  int addSpecies(rbfParticleSpecies? SPECIES) {
    fbBuilder.addInt8(7, SPECIES?.value);
    return fbBuilder.offset;
  }
  int addFluxType(rbfFluxKind? FLUX_TYPE) {
    fbBuilder.addInt8(8, FLUX_TYPE?.value);
    return fbBuilder.offset;
  }
  int addUnitsOffset(int? offset) {
    fbBuilder.addOffset(9, offset);
    return fbBuilder.offset;
  }
  int addEpochOffset(int? offset) {
    fbBuilder.addOffset(10, offset);
    return fbBuilder.offset;
  }
  int addKp(double? KP) {
    fbBuilder.addFloat64(11, KP);
    return fbBuilder.offset;
  }
  int addHasKp(bool? HAS_KP) {
    fbBuilder.addBool(12, HAS_KP);
    return fbBuilder.offset;
  }
  int addDstNt(double? DST_NT) {
    fbBuilder.addFloat64(13, DST_NT);
    return fbBuilder.offset;
  }
  int addHasDstNt(bool? HAS_DST_NT) {
    fbBuilder.addBool(14, HAS_DST_NT);
    return fbBuilder.offset;
  }
  int addF107(double? F107) {
    fbBuilder.addFloat64(15, F107);
    return fbBuilder.offset;
  }
  int addHasF107(bool? HAS_F107) {
    fbBuilder.addBool(16, HAS_F107);
    return fbBuilder.offset;
  }
  int addSolarWindPressureNpa(double? SOLAR_WIND_PRESSURE_NPA) {
    fbBuilder.addFloat64(17, SOLAR_WIND_PRESSURE_NPA);
    return fbBuilder.offset;
  }
  int addHasSolarWindPressure(bool? HAS_SOLAR_WIND_PRESSURE) {
    fbBuilder.addBool(18, HAS_SOLAR_WIND_PRESSURE);
    return fbBuilder.offset;
  }
  int addQuantilePct(double? QUANTILE_PCT) {
    fbBuilder.addFloat64(19, QUANTILE_PCT);
    return fbBuilder.offset;
  }
  int addLShellsOffset(int? offset) {
    fbBuilder.addOffset(20, offset);
    return fbBuilder.offset;
  }
  int addEnergyMevOffset(int? offset) {
    fbBuilder.addOffset(21, offset);
    return fbBuilder.offset;
  }
  int addBOverB0Offset(int? offset) {
    fbBuilder.addOffset(22, offset);
    return fbBuilder.offset;
  }
  int addFluxGridOffset(int? offset) {
    fbBuilder.addOffset(23, offset);
    return fbBuilder.offset;
  }
  int addStructuresOffset(int? offset) {
    fbBuilder.addOffset(24, offset);
    return fbBuilder.offset;
  }
  int addSaaContoursOffset(int? offset) {
    fbBuilder.addOffset(25, offset);
    return fbBuilder.offset;
  }
  int addSpaceWeatherRefsOffset(int? offset) {
    fbBuilder.addOffset(26, offset);
    return fbBuilder.offset;
  }
  int addProvenanceOffset(int? offset) {
    fbBuilder.addOffset(27, offset);
    return fbBuilder.offset;
  }

  int finish() {
