class RBFObjectBuilder extends fb.ObjectBuilder {
  final String? _RBF_ID;
  final String? _BODY_NAME;
  final int? _BODY_NAIF_ID;
  final rbfModelKind? _MODEL;
  final String? _MODEL_VERSION;
  final String? _MAG_MODEL_ID;
  final String? _REFERENCE_FRAME;
  final rbfParticleSpecies? _SPECIES;
  final rbfFluxKind? _FLUX_TYPE;
  final String? _UNITS;
  final String? _EPOCH;
  final double? _KP;
  final bool? _HAS_KP;
  final double? _DST_NT;
  final bool? _HAS_DST_NT;
  final double? _F107;
  final bool? _HAS_F107;
  final double? _SOLAR_WIND_PRESSURE_NPA;
  final bool? _HAS_SOLAR_WIND_PRESSURE;
  final double? _QUANTILE_PCT;
  final List<double>? _L_SHELLS;
  final List<double>? _ENERGY_MEV;
  final List<double>? _B_OVER_B0;
  final List<double>? _FLUX_GRID;
  final List<RBFStructureFeatureObjectBuilder>? _STRUCTURES;
  final List<RBFSaaContourObjectBuilder>? _SAA_CONTOURS;
  final List<String>? _SPACE_WEATHER_REFS;
  final PVNObjectBuilder? _PROVENANCE;

  RBFObjectBuilder({
    String? RBF_ID,
    String? rbfId,
    String? BODY_NAME,
    String? bodyName,
    int? BODY_NAIF_ID,
    int? bodyNaifId,
    rbfModelKind? MODEL,
    String? MODEL_VERSION,
    String? modelVersion,
    String? MAG_MODEL_ID,
    String? magModelId,
    String? REFERENCE_FRAME,
    String? referenceFrame,
    rbfParticleSpecies? SPECIES,
    rbfFluxKind? FLUX_TYPE,
    rbfFluxKind? fluxType,
    String? UNITS,
    String? EPOCH,
    double? KP,
    bool? HAS_KP,
    bool? hasKp,
    double? DST_NT,
    double? dstNt,
    bool? HAS_DST_NT,
    bool? hasDstNt,
    double? F107,
    bool? HAS_F107,
    bool? hasF107,
    double? SOLAR_WIND_PRESSURE_NPA,
    double? solarWindPressureNpa,
    bool? HAS_SOLAR_WIND_PRESSURE,
    bool? hasSolarWindPressure,
    double? QUANTILE_PCT,
    double? quantilePct,
    List<double>? L_SHELLS,
    List<double>? lShells,
    List<double>? ENERGY_MEV,
    List<double>? energyMev,
    List<double>? B_OVER_B0,
    List<double>? bOverB0,
    List<double>? FLUX_GRID,
    List<double>? fluxGrid,
    List<RBFStructureFeatureObjectBuilder>? STRUCTURES,
    List<RBFSaaContourObjectBuilder>? SAA_CONTOURS,
    List<RBFSaaContourObjectBuilder>? saaContours,
    List<String>? SPACE_WEATHER_REFS,
    List<String>? spaceWeatherRefs,
    PVNObjectBuilder? PROVENANCE,
  })
      : _RBF_ID = rbfId ?? RBF_ID,
        _BODY_NAME = bodyName ?? BODY_NAME,
        _BODY_NAIF_ID = bodyNaifId ?? BODY_NAIF_ID,
        _MODEL = MODEL,
        _MODEL_VERSION = modelVersion ?? MODEL_VERSION,
        _MAG_MODEL_ID = magModelId ?? MAG_MODEL_ID,
        _REFERENCE_FRAME = referenceFrame ?? REFERENCE_FRAME,
        _SPECIES = SPECIES,
        _FLUX_TYPE = fluxType ?? FLUX_TYPE,
        _UNITS = UNITS,
        _EPOCH = EPOCH,
        _KP = KP,
        _HAS_KP = hasKp ?? HAS_KP,
        _DST_NT = dstNt ?? DST_NT,
        _HAS_DST_NT = hasDstNt ?? HAS_DST_NT,
        _F107 = F107,
        _HAS_F107 = hasF107 ?? HAS_F107,
        _SOLAR_WIND_PRESSURE_NPA = solarWindPressureNpa ?? SOLAR_WIND_PRESSURE_NPA,
        _HAS_SOLAR_WIND_PRESSURE = hasSolarWindPressure ?? HAS_SOLAR_WIND_PRESSURE,
        _QUANTILE_PCT = quantilePct ?? QUANTILE_PCT,
        _L_SHELLS = lShells ?? L_SHELLS,
        _ENERGY_MEV = energyMev ?? ENERGY_MEV,
        _B_OVER_B0 = bOverB0 ?? B_OVER_B0,
        _FLUX_GRID = fluxGrid ?? FLUX_GRID,
        _STRUCTURES = STRUCTURES,
        _SAA_CONTOURS = saaContours ?? SAA_CONTOURS,
        _SPACE_WEATHER_REFS = spaceWeatherRefs ?? SPACE_WEATHER_REFS,
        _PROVENANCE = PROVENANCE;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? RBF_IDOffset = _RBF_ID == null ? null
        : fbBuilder.writeString(_RBF_ID!);
    final int? BODY_NAMEOffset = _BODY_NAME == null ? null
        : fbBuilder.writeString(_BODY_NAME!);
    final int? MODEL_VERSIONOffset = _MODEL_VERSION == null ? null
        : fbBuilder.writeString(_MODEL_VERSION!);
    final int? MAG_MODEL_IDOffset = _MAG_MODEL_ID == null ? null
        : fbBuilder.writeString(_MAG_MODEL_ID!);
    final int? REFERENCE_FRAMEOffset = _REFERENCE_FRAME == null ? null
        : fbBuilder.writeString(_REFERENCE_FRAME!);
    final int? UNITSOffset = _UNITS == null ? null
        : fbBuilder.writeString(_UNITS!);
    final int? EPOCHOffset = _EPOCH == null ? null
        : fbBuilder.writeString(_EPOCH!);
    final int? L_SHELLSOffset = _L_SHELLS == null ? null
        : fbBuilder.writeListFloat64(_L_SHELLS!);
    final int? ENERGY_MEVOffset = _ENERGY_MEV == null ? null
        : fbBuilder.writeListFloat64(_ENERGY_MEV!);
    final int? B_OVER_B0Offset = _B_OVER_B0 == null ? null
        : fbBuilder.writeListFloat64(_B_OVER_B0!);
    final int? FLUX_GRIDOffset = _FLUX_GRID == null ? null
        : fbBuilder.writeListFloat64(_FLUX_GRID!);
    final int? STRUCTURESOffset = _STRUCTURES == null ? null
        : fbBuilder.writeList(_STRUCTURES!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? SAA_CONTOURSOffset = _SAA_CONTOURS == null ? null
        : fbBuilder.writeList(_SAA_CONTOURS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? SPACE_WEATHER_REFSOffset = _SPACE_WEATHER_REFS == null ? null
        : fbBuilder.writeList(_SPACE_WEATHER_REFS!.map(fbBuilder.writeString).toList());
    final int? PROVENANCEOffset = _PROVENANCE?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(28);
    fbBuilder.addOffset(0, RBF_IDOffset);
    fbBuilder.addOffset(1, BODY_NAMEOffset);
    fbBuilder.addInt32(2, _BODY_NAIF_ID);
    fbBuilder.addInt8(3, _MODEL?.value);
    fbBuilder.addOffset(4, MODEL_VERSIONOffset);
    fbBuilder.addOffset(5, MAG_MODEL_IDOffset);
    fbBuilder.addOffset(6, REFERENCE_FRAMEOffset);
    fbBuilder.addInt8(7, _SPECIES?.value);
    fbBuilder.addInt8(8, _FLUX_TYPE?.value);
    fbBuilder.addOffset(9, UNITSOffset);
    fbBuilder.addOffset(10, EPOCHOffset);
    fbBuilder.addFloat64(11, _KP);
    fbBuilder.addBool(12, _HAS_KP);
    fbBuilder.addFloat64(13, _DST_NT);
    fbBuilder.addBool(14, _HAS_DST_NT);
    fbBuilder.addFloat64(15, _F107);
    fbBuilder.addBool(16, _HAS_F107);
    fbBuilder.addFloat64(17, _SOLAR_WIND_PRESSURE_NPA);
    fbBuilder.addBool(18, _HAS_SOLAR_WIND_PRESSURE);
    fbBuilder.addFloat64(19, _QUANTILE_PCT);
    fbBuilder.addOffset(20, L_SHELLSOffset);
    fbBuilder.addOffset(21, ENERGY_MEVOffset);
    fbBuilder.addOffset(22, B_OVER_B0Offset);
    fbBuilder.addOffset(23, FLUX_GRIDOffset);
    fbBuilder.addOffset(24, STRUCTURESOffset);
    fbBuilder.addOffset(25, SAA_CONTOURSOffset);
    fbBuilder.addOffset(26, SPACE_WEATHER_REFSOffset);
    fbBuilder.addOffset(27, PROVENANCEOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
